import{_ as e,o,c as l,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"액션 메뉴 및 즉시 미리보기","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/actions-and-preview.md","filePath":"ko-KR/user-guide/actions-and-preview.md","lastUpdated":1788250223000}'),a={name:"ko-KR/user-guide/actions-and-preview.md"};function n(i,t,s,d,g,c){return o(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="액션-메뉴-및-즉시-미리보기" tabindex="-1">액션 메뉴 및 즉시 미리보기 <a class="header-anchor" href="#액션-메뉴-및-즉시-미리보기" aria-label="Permalink to &quot;액션 메뉴 및 즉시 미리보기&quot;">​</a></h1><p>Lertaro는 초고속 파일 검색뿐만 아니라 강력한 컨텍스트 액션 시스템과 다채로운 미리보기 패널을 통합하여, 파일 탐색기를 열지 않고도 파일 검토, 관리 및 실행을 빠르게 완료할 수 있습니다.</p><h2 id="_1-액션-메뉴-상세-안내" tabindex="-1">1. 액션 메뉴 상세 안내 <a class="header-anchor" href="#_1-액션-메뉴-상세-안내" aria-label="Permalink to &quot;1. 액션 메뉴 상세 안내&quot;">​</a></h2><p>검색 결과(파일, 폴더, 앱, 플러그인 항목)에서 <code>Ctrl+O</code> 또는 방향키 <code>→</code>를 누르면 컨텍스트 액션 메뉴가 펼쳐집니다.</p><h3 id="기본-핵심-액션-목록" tabindex="-1">기본 핵심 액션 목록 <a class="header-anchor" href="#기본-핵심-액션-목록" aria-label="Permalink to &quot;기본 핵심 액션 목록&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">액션 이름</th><th style="text-align:left;">기본 단축키</th><th style="text-align:left;">기능 설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>열기</strong></td><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">시스템 기본 연결 프로그램으로 파일을 열거나 응용 프로그램을 실행합니다.</td></tr><tr><td style="text-align:left;"><strong>탐색기에서 위치 확인</strong></td><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">상위 폴더를 열고 파일 탐색기에서 해당 파일을 선택한 상태로 표시합니다.</td></tr><tr><td style="text-align:left;"><strong>관리자 권한으로 실행</strong></td><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">관리자 권한으로 프로그램을 실행합니다(실행 파일, 바로가기, 배치 스크립트 등).</td></tr><tr><td style="text-align:left;"><strong>전체 경로 복사</strong></td><td style="text-align:left;"><code>Ctrl+Shift+C</code></td><td style="text-align:left;">파일의 절대 경로(예: <code>D:\\Projects\\app.exe</code>)를 클립보드에 복사합니다.</td></tr><tr><td style="text-align:left;"><strong>파일 잘라내기 / 복사</strong></td><td style="text-align:left;"><code>Ctrl+X</code> / <code>Ctrl+C</code></td><td style="text-align:left;">파일 자체를 클립보드에 담아 탐색기나 다른 폴더에 직접 붙여넣을 수 있게 합니다.</td></tr><tr><td style="text-align:left;"><strong>여기에 붙여넣기</strong></td><td style="text-align:left;"><code>Ctrl+V</code></td><td style="text-align:left;">선택 항목이 폴더인 경우 클립보드의 파일을 해당 디렉토리 내에 붙여넣습니다.</td></tr><tr><td style="text-align:left;"><strong>삭제 (휴지통으로 이동)</strong></td><td style="text-align:left;"><code>Delete</code></td><td style="text-align:left;">선택한 파일이나 폴더를 Windows 휴지통으로 안전하게 이동합니다.</td></tr><tr><td style="text-align:left;"><strong>영구 삭제</strong></td><td style="text-align:left;"><code>Shift+Delete</code></td><td style="text-align:left;">선택 항목을 영구적으로 삭제합니다(복구 불가, 확인 대화상자 표시).</td></tr><tr><td style="text-align:left;"><strong>Windows 우클릭 메뉴</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">Windows 파일 탐색기의 전체 기본 컨텍스트 메뉴(보내기 및 타사 확장 메뉴 포함)를 엽니다.</td></tr></tbody></table><h3 id="액션-메뉴-인터랙션-및-즉시-필터링" tabindex="-1">액션 메뉴 인터랙션 및 즉시 필터링 <a class="header-anchor" href="#액션-메뉴-인터랙션-및-즉시-필터링" aria-label="Permalink to &quot;액션 메뉴 인터랙션 및 즉시 필터링&quot;">​</a></h3><ul><li><strong>입력하여 즉시 필터링</strong>: 액션 메뉴가 열린 상태에서 글자를 입력하면 액션 이름을 실시간으로 검색할 수 있습니다(예: <code>copy</code> 입력 시 복사 관련 액션 즉시 표시).</li><li><strong>계층 탐색</strong>: 하위 메뉴가 있는 항목(예: &quot;보내기&quot;)에서 <code>→</code> 또는 <code>Enter</code>를 눌러 진입하고, <code>←</code> 또는 검색어가 빈 상태에서 <code>Backspace</code>를 누르면 상위로 돌아갑니다.</li><li><strong>메뉴 닫기</strong>: <code>Escape</code>를 누르면 액션 메뉴를 닫고 검색 목록으로 돌아갑니다.</li></ul><h2 id="_2-메인-윈도우-결과-목록-기능" tabindex="-1">2. 메인 윈도우 결과 목록 기능 <a class="header-anchor" href="#_2-메인-윈도우-결과-목록-기능" aria-label="Permalink to &quot;2. 메인 윈도우 결과 목록 기능&quot;">​</a></h2><p>메인 검색 윈도우(<code>Ctrl+F</code>)는 대규모 파일 관리와 심층 탐색을 위해 설계되었습니다.</p><ul><li><strong>경로 열 더블클릭 이동</strong>: 목록의 <strong>이름</strong> 열을 더블클릭하면 파일이 실행되고, <strong>경로</strong> 열을 더블클릭하면 해당 파일이 위치한 상위 폴더가 열립니다.</li><li><strong>스트리밍 결과 로딩</strong>: 수백만 개의 항목을 스캔할 때도 인덱싱 엔진에서 수신된 결과가 목록에 실시간 스트리밍 방식으로 추가됩니다. 전체 스캔 완료를 기다릴 필요 없이 즉시 조작할 수 있습니다.</li><li><strong>루프 탐색</strong>: 첫 번째 행에서 <code>↑</code>를 누르면 마지막 행으로, 마지막 행에서 <code>↓</code>를 누르면 첫 번째 행으로 이동합니다.</li><li><strong>창 드래그 및 크기 기억</strong>: 창 상단의 빈 영역을 드래그하여 위치를 옮길 수 있으며, 조절된 크기는 다음 실행 시에도 유지됩니다.</li></ul><h2 id="_3-quicklook-즉시-미리보기-기능" tabindex="-1">3. QuickLook 즉시 미리보기 기능 <a class="header-anchor" href="#_3-quicklook-즉시-미리보기-기능" aria-label="Permalink to &quot;3. QuickLook 즉시 미리보기 기능&quot;">​</a></h2><p>검색 결과에서 <code>Alt+P</code>를 누르면 검색창 옆에 강력한 미리보기 패널이 열립니다.</p><h3 id="다양한-파일-형식-지원" tabindex="-1">다양한 파일 형식 지원 <a class="header-anchor" href="#다양한-파일-형식-지원" aria-label="Permalink to &quot;다양한 파일 형식 지원&quot;">​</a></h3><ul><li><strong>이미지 및 벡터 그래픽</strong>: JPG, PNG, GIF(움짤 자동 재생), BMP, WebP, ICO, SVG 등의 고해상도 렌더링.</li><li><strong>문서 및 코드 구문 강조</strong>: TXT, Markdown, JSON, XML, YAML, C#, Python, JS, HTML 등의 텍스트 서식 표시.</li><li><strong>오디오/비디오 즉시 재생</strong>: MP4, MKV, AVI, MOV, WMV, MP3, WAV, FLAC, WMA 등의 미디어는 미리보기가 열리는 즉시 <strong>자동 재생</strong>되며 미니 컨트롤 바(재생/일시정지, 탐색 바, 시간 표시, 음소거)가 제공됩니다. 항목 전환 시 즉시 중지됩니다.</li><li><strong>폴더 구조 검사</strong>: 폴더를 선택하면 직속 하위 항목 최대 30개가 아이콘 및 크기와 함께 표시됩니다(숨김/시스템 파일 제외).</li></ul><h3 id="레이아웃-및-대화상자-자동-회피" tabindex="-1">레이아웃 및 대화상자 자동 회피 <a class="header-anchor" href="#레이아웃-및-대화상자-자동-회피" aria-label="Permalink to &quot;레이아웃 및 대화상자 자동 회피&quot;">​</a></h3><ul><li><strong>화면 영역 자동 맞춤</strong>: 미리보기 크기는 <a href="./settings/general.html#미리보기"><strong>설정 → 일반 → 미리보기</strong></a>에서 변경할 수 있으며 화면을 벗어나지 않도록 자동 제어됩니다.</li><li><strong>네이티브 대화상자 자동 회피</strong>: 비밀번호가 걸린 Office 문서를 미리볼 때 암호 입력 창이 뜨면 Lertaro 창을 일시적으로 숨겨 입력을 방해하지 않으며, 완료 후 자동으로 복구됩니다.</li><li><strong>미리보기 창에서 드래그 앤 드롭</strong>: 미리보기 패널 상단을 드래그하여 외부 앱이나 탐색기로 파일을 직접 끌어다 놓을 수 있습니다.</li></ul><h2 id="_4-플러그인-리치-텍스트-및-대화형-미리보기" tabindex="-1">4. 플러그인 리치 텍스트 및 대화형 미리보기 <a class="header-anchor" href="#_4-플러그인-리치-텍스트-및-대화형-미리보기" aria-label="Permalink to &quot;4. 플러그인 리치 텍스트 및 대화형 미리보기&quot;">​</a></h2><p>QuickLook은 로컬 파일뿐 아니라 플러그인의 인터랙티브 패널도 지원합니다.</p><ul><li><strong>테마 자동 적응형 리치 텍스트</strong>: WebView2 및 네이티브 컴포넌트로 렌더링되어 다크/라이트 테마에 자동 맞춤되며 깔끔한 타이포그래피와 반투명 스크롤바를 제공합니다.</li><li><strong>다양한 플러그인 카드</strong>: 사전 검색 카드, 실시간 날씨, 웹 스냅샷, API 디버깅 정보 등 풍부한 인터랙티브 패널을 지원합니다.</li></ul><h2 id="_5-타사-독립-quicklook-연동-선택-사항" tabindex="-1">5. 타사 독립 QuickLook 연동 (선택 사항) <a class="header-anchor" href="#_5-타사-독립-quicklook-연동-선택-사항" aria-label="Permalink to &quot;5. 타사 독립 QuickLook 연동 (선택 사항)&quot;">​</a></h2><p>독립된 오픈소스 도구인 <strong>QuickLook</strong>(<a href="https://github.com/QL-Win/QuickLook" target="_blank" rel="noreferrer">GitHub의 QL-Win/QuickLook</a>)을 설치하여 사용 중인 경우, <a href="./settings/plugins.html"><strong>설정 → 플러그인</strong></a>에서 <strong>QuickLook 브리지</strong> 플러그인을 활성화할 수 있습니다.</p><ul><li><strong>외부 미리보기 연결</strong>: 로컬 명명된 파이프를 통해 외부 QuickLook 프로세스에 연결하여 미리보기 창을 Lertaro 옆에 도킹합니다.</li><li><strong>자동 대체</strong>: 외부 QuickLook 프로세스가 실행 중이지 않은 경우 내장 미리보기 엔진으로 부드럽게 대체됩니다.</li></ul><h2 id="_6-파일-점유-해제" tabindex="-1">6. 파일 점유 해제 <a class="header-anchor" href="#_6-파일-점유-해제" aria-label="Permalink to &quot;6. 파일 점유 해제&quot;">​</a></h2><p>공식 <strong>파일 점유 해제</strong> 플러그인은 존재하는 파일을 하나만 선택했을 때 사용할 수 있는 액션을 제공합니다. 파일을 사용 중인 프로세스와 PID, 실행 파일 경로를 표시하고 해당 프로세스에 파일 해제를 요청합니다. 폴더, 존재하지 않는 파일 또는 여러 항목을 선택하면 액션을 사용할 수 없으며, 점유 프로세스가 없을 때는 해제 요청 버튼도 비활성화됩니다. 대화상자는 호스트 테마를 사용하고 검색 창 위에 표시되며 Alt+Tab 목록에는 나타나지 않습니다. 새로 고침도 지원합니다.</p><h2 id="_7-즐겨찾기에-추가" tabindex="-1">7. 즐겨찾기에 추가 <a class="header-anchor" href="#_7-즐겨찾기에-추가" aria-label="Permalink to &quot;7. 즐겨찾기에 추가&quot;">​</a></h2><p>CoreExtensions는 존재하는 파일 또는 폴더 하나를 즐겨찾기에 추가하는 <strong>즐겨찾기에 추가</strong> 액션을 제공합니다. 테마가 적용된 대화상자에서 표시 이름을 입력할 수 있으며, 같은 경로가 이미 즐겨찾기에 있으면 액션을 표시하지 않습니다.</p>',27)])])}const f=e(a,[["render",n]]);export{u as __pageData,f as default};
